/**
 * Source of truth for registry.json (generated by scripts/build-registry.ts)
 * and for the site's catalog (home showcase, group index pages, llms.txt).
 *
 * Item names mirror the docs URLs: bare slugs for UI components and cores
 * (`tabs`, installed as `@transition-kit/tabs`), `theme/<slug>` and
 * `page/<slug>` for styles.
 * - core: the React 19.3 <ViewTransition> wrapper for the group.
 * - style: one CSS file (registry/<group>/styles/<slug>.css), merged into the
 *   user's global CSS by the shadcn CLI. Depends on the group's core.
 * - component: a ready-made control built on the core.
 */
export type ItemGroup = "theme" | "page" | "ui";
export type ItemKind = "core" | "style" | "component";

export interface ItemSource {
  /**
   * Public install name. UI components and cores use the bare slug
   * (`tabs`); styles keep their group (`theme/circle-reveal`).
   */
  name: string;
  title: string;
  description: string;
  group: ItemGroup;
  kind: ItemKind;
  /** Source files under registry/. Components and cores install to components/transitions/. */
  files: string[];
  /**
   * CSS file(s) under registry/, shipped as the item's `css`. Cores bundle
   * their default style's CSS so installing the core animates immediately.
   */
  css?: string | string[];
  /** Preview video under public/. */
  video?: string;
  isNew?: boolean;
  /**
   * Skip the automatic dependency on the item's group core. Used by components
   * that live in one group but are built on another group's core (the theme
   * toggles live in `ui` and depend on the `theme` core through their imports).
   */
  omitGroupCore?: boolean;
}

const themeStyle = (
  slug: string,
  title: string,
  description: string,
  video: string,
  isNew = false
): ItemSource => ({
  css: `registry/theme/styles/${slug}.css`,
  description,
  files: [],
  group: "theme",
  isNew,
  kind: "style",
  name: `theme/${slug}`,
  title,
  video: `/demos/theme-toggles/${video}`,
});

const pageStyle = (
  slug: string,
  title: string,
  description: string,
  video: string,
  isNew = false
): ItemSource => ({
  css: `registry/page/styles/${slug}.css`,
  description,
  files: [],
  group: "page",
  isNew,
  kind: "style",
  name: `page/${slug}`,
  title,
  video: `/demos/page-transitions/${video}`,
});

const uiToggle = (
  slug: string,
  title: string,
  description: string
): ItemSource => ({
  description,
  files: [`registry/ui/${slug}.tsx`],
  group: "ui",
  kind: "component",
  name: slug,
  omitGroupCore: true,
  title,
});

